def equal_count_substrings(s: str, count: int) -> int:
    n = len(s)
    codes = [ord(c) - 97 for c in s]
    result = 0
    for distinct in range(1, 27):
        width = distinct * count
        if width > n:
            break
        freq = [0] * 26
        good = 0  # letters whose frequency equals count
        for i in range(n):
            c = codes[i]
            freq[c] += 1
            if freq[c] == count:
                good += 1
            elif freq[c] == count + 1:
                good -= 1
            if i >= width:
                out = codes[i - width]
                if freq[out] == count:
                    good -= 1
                elif freq[out] == count + 1:
                    good += 1
                freq[out] -= 1
            if i >= width - 1 and good == distinct:
                result += 1
    return result

