def distribute_cookies(cookies: list[int], k: int) -> int:
    bags = sorted(cookies, reverse=True)   # big bags first prunes sooner
    totals = [0] * k
    best = sum(bags)

    def place(i):
        nonlocal best
        if i == len(bags):
            best = min(best, max(totals))
            return
        for child in range(k):
            if totals[child] + bags[i] >= best:
                continue   # cannot improve on the best found so far
            totals[child] += bags[i]
            place(i + 1)
            totals[child] -= bags[i]
            if totals[child] == 0:
                break      # every other empty child would give the same branches

    place(0)
    return best

