def expressive_words(s: str, words: list[str]) -> int:
    def stretchy(word):
        i = j = 0
        while i < len(s) and j < len(word):
            if s[i] != word[j]:
                return False
            ch = s[i]
            i2 = i
            while i2 < len(s) and s[i2] == ch:
                i2 += 1
            j2 = j
            while j2 < len(word) and word[j2] == ch:
                j2 += 1
            a, b = i2 - i, j2 - j   # run lengths in s and in word
            if a < b or (a != b and a < 3):
                return False
            i, j = i2, j2
        return i == len(s) and j == len(word)

