def count_paths(n: int, edges: list[list[int]]) -> int:
    # sieve of Eratosthenes over labels 1..n
    is_prime = [True] * (n + 1)
    is_prime[0] = False
    if n >= 1:
        is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False

    # union find over non prime nodes
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:   # path compression
            parent[x], x = root, parent[x]
        return root

    adjacency = [[] for _ in range(n + 1)]
    for u, v in edges:
        adjacency[u].append(v)
        adjacency[v].append(u)
        if not is_prime[u] and not is_prime[v]:
            ru, rv = find(u), find(v)
            if ru != rv:
                if size[ru] < size[rv]:
                    ru, rv = rv, ru
                parent[rv] = ru
                size[ru] += size[rv]

    total = 0
    for p in range(2, n + 1):
        if not is_prime[p]:
            continue
        seen = 0   # non prime nodes reachable from p through earlier neighbours
        for q in adjacency[p]:
            if is_prime[q]:
                continue
            s = size[find(q)]
            total += s * (1 + seen)   # p as endpoint, or p joining two components
            seen += s
    return total

def num_squareful_perms(nums: list[int]) -> int:
    remaining = Counter(nums)
    values = list(remaining)

    def is_square(x):
        r = math.isqrt(x)
        return r * r == x

    # neighbours[v]: distinct values whose sum with v is a perfect square
    neighbours = {v: [w for w in values if is_square(v + w)] for v in values}
    n = len(nums)

    def extend(last, placed):
        if placed == n:
            return 1
        total = 0
        for w in neighbours[last]:
            if remaining[w]:
                remaining[w] -= 1
                total += extend(w, placed + 1)
                remaining[w] += 1
        return total

    count = 0
    for v in values:
        remaining[v] -= 1
        count += extend(v, 1)
        remaining[v] += 1
    return count

def unhappy_friends(n: int, preferences: list[list[int]], pairs: list[list[int]]) -> int:
    # rank[i][u] = how far down u sits in i's list (0 = favourite)
    rank = [[0] * n for _ in range(n)]
    for i, prefs in enumerate(preferences):
        for position, u in enumerate(prefs):
            rank[i][u] = position
    partner = [0] * n
    for x, y in pairs:
        partner[x] = y
        partner[y] = x

    unhappy = 0
    for x in range(n):
        y = partner[x]
        for u in preferences[x]:
            if u == y:
                break   # everything after the partner is liked less than the partner
            v = partner[u]
            if rank[u][x] < rank[u][v]:
                unhappy += 1
                break
    return unhappy

