def moves_to_stamp(stamp: str, target: str) -> list[int]:
    m, n = len(stamp), len(target)
    windows = n - m + 1
    todo = []           # todo[w] = positions in window w that still mismatch the stamp
    queue = deque()     # windows whose mismatch set is empty (ready to be undone)
    for w in range(windows):
        bad = {w + j for j in range(m) if target[w + j] != stamp[j]}
        todo.append(bad)
        if not bad:
            queue.append(w)
    done = [False] * n  # done[p]: position p has been turned into a wildcard
    order = []
    while queue:
        w = queue.popleft()
        order.append(w)
        for pos in range(w, w + m):
            if done[pos]:
                continue
            done[pos] = True
            # Every window covering pos no longer mismatches there.
            for other in range(max(0, pos - m + 1), min(pos, windows - 1) + 1):
                if pos in todo[other]:
                    todo[other].discard(pos)
                    if not todo[other]:
                        queue.append(other)
    if not all(done):
        return []
    order.reverse()     # undo order reversed is a valid stamping order
    return order

