class Promise:
    def __init__(self, executor=None):
        self.state = "pending"        # "pending" or "fulfilled"
        self.value = None
        self._callbacks = []
        if executor is not None:
            executor(self._resolve)

    def _resolve(self, value):
        if self.state != "pending":
            return
        if isinstance(value, Promise):
            value.then(self._resolve)
            return
        self.state, self.value = "fulfilled", value
        callbacks, self._callbacks = self._callbacks, []
        for cb in callbacks:
            cb(value)

    def then(self, on_fulfilled):
        """Return a new Promise that resolves with on_fulfilled(value)."""
        child = Promise()

        def settle(v):
            child._resolve(on_fulfilled(v))
        if self.state == "fulfilled":
            settle(self.value)
        else:
            self._callbacks.append(settle)
        return child

    @staticmethod
    def resolve(value):
        p = Promise()
        p._resolve(value)
        return p

    @staticmethod
    def all(promises):
        """Resolve with the list of values once every promise has resolved."""
        promises = list(promises)
        result = Promise()
        values = [None] * len(promises)
        remaining = [len(promises)]
        if not promises:
            result._resolve([])
            return result
        for i, p in enumerate(promises):
            def done(v, i=i):
                values[i] = v
                remaining[0] -= 1
                if remaining[0] == 0:
                    result._resolve(values)
            p.then(done)
        return result

