    prev = 0                               # final value of the previous element
    for x in nums:
        # Largest prime p with p < x - prev keeps the result strictly above prev.
        idx = bisect.bisect_left(primes, x - prev) - 1
        if idx >= 0:
            x -= primes[idx]
        if x <= prev:
            return False
        prev = x
    return True

class NumMatrix:
    def __init__(self, matrix: list[list[int]]):
        self.m, self.n = len(matrix), len(matrix[0])
        self.vals = [row[:] for row in matrix]
        # 1-indexed 2D Fenwick tree, built in O(m * n) with a linear pass per dimension.
        tree = [[0] * (self.n + 1) for _ in range(self.m + 1)]
        for r in range(1, self.m + 1):
            row = tree[r]
            row[1:] = matrix[r - 1]
            for c in range(1, self.n + 1):
                parent = c + (c & -c)
                if parent <= self.n:
                    row[parent] += row[c]
        for r in range(1, self.m + 1):
            parent = r + (r & -r)
            if parent <= self.m:
                trow, prow = tree[r], tree[parent]
                for c in range(1, self.n + 1):
                    prow[c] += trow[c]
        self.tree = tree

    def _add(self, row: int, col: int, delta: int) -> None:
        r = row + 1
        while r <= self.m:
            trow = self.tree[r]
            c = col + 1
            while c <= self.n:
                trow[c] += delta
                c += c & -c
            r += r & -r

    def _prefix(self, row: int, col: int) -> int:
        # Sum of the rectangle (0, 0) .. (row, col), inclusive; row or col may be -1.
        total = 0
        r = row + 1
        while r > 0:
            trow = self.tree[r]
            c = col + 1
            while c > 0:
                total += trow[c]
                c -= c & -c
            r -= r & -r
        return total

    def update(self, row: int, col: int, val: int) -> None:
        self._add(row, col, val - self.vals[row][col])
        self.vals[row][col] = val

    def sumRegion(self, row1: int, col1: int, row2: int, col2: int) -> int:
        return (self._prefix(row2, col2) - self._prefix(row1 - 1, col2)
                - self._prefix(row2, col1 - 1) + self._prefix(row1 - 1, col1 - 1))

