def longest_subsequence(s: str, k: int) -> int:
    kept = 0      # characters already chosen (all of them lie to the right)
    value = 0     # binary value of the chosen suffix subsequence
    for ch in reversed(s):
        if ch == "0":
            kept += 1                       # zeros are free
        elif kept < 31 and value + (1 << kept) <= k:
            value += 1 << kept              # this one lands at bit position `kept`
            kept += 1
    return kept

def earliest_and_latest(n: int, first_player: int, second_player: int) -> List[int]:
    memo = {}

    def solve(count: int, a: int, b: int) -> Tuple[int, int]:
        # a < b are 1-based positions of the strongest players among `count` players
        if a + b == count + 1:
            return (1, 1)                       # they face each other now
        if a + b > count + 1:
            a, b = count + 1 - b, count + 1 - a   # mirror so that a + b <= count + 1
        key = (count, a, b)
        if key in memo:
            return memo[key]
        nxt = (count + 1) // 2
        earliest, latest = float("inf"), 0
        if b <= nxt:
            # both in the left half: players between them all face someone outside
            for i in range(a):                  # winners from the left of a
                for j in range(b - a):          # winners from strictly between a and b
                    e, l = solve(nxt, i + 1, i + j + 2)
                    earliest = min(earliest, e + 1)
                    latest = max(latest, l + 1)
        else:
            mirror_b = count + 1 - b            # b's opponent position, lies between a and b
            fixed = (count - 2 * mirror_b + 1) // 2   # survivors of the self paired middle block
            for i in range(a):
                for j in range(mirror_b - a):
                    e, l = solve(nxt, i + 1, i + j + fixed + 2)
                    earliest = min(earliest, e + 1)
                    latest = max(latest, l + 1)
        memo[key] = (earliest, latest)
        return memo[key]

    e, l = solve(n, first_player, second_player)
    return [e, l]

