class Solution:
    def read(self, buf: List[str], n: int) -> int:
        block = [""] * 4
        copied = 0
        while copied < n:
            fetched = read4(block)
            if fetched == 0:
                break                               # end of file
            take = min(fetched, n - copied)         # do not exceed the request
            for i in range(take):
                buf[copied + i] = block[i]
            copied += take
            if fetched < 4:
                break                               # short block means the file ended
        return copied

