def get_maximum_xor(nums: List[int], maximum_bit: int) -> List[int]:
    mask = (1 << maximum_bit) - 1
    total = 0
    for v in nums:
        total ^= v                      # XOR of the whole array
    answer = []
    for i in range(len(nums) - 1, -1, -1):
        answer.append(total ^ mask)     # complement within maximum_bit bits
        total ^= nums[i]                # remove the last remaining element
    return answer

