def find_root(nodes: List["Node"]) -> "Node":
    balance = 0
    for node in nodes:
        balance += node.val               # every node is counted once as itself
        for child in node.children:
            balance -= child.val          # and once as a child, except the root
    for node in nodes:
        if node.val == balance:
            return node
    return None

def count_alternating_subarrays(nums: List[int]) -> int:
    total = 0
    run = 0                         # alternating subarrays ending at the current index
    for i, v in enumerate(nums):
        if i > 0 and v != nums[i - 1]:
            run += 1                # extend every subarray ending at i - 1, plus [v] itself
        else:
            run = 1                 # only [v] alternates
        total += run
    return total

