def count(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    MOD = 10 ** 9 + 7

    def upto(x: str) -> int:
        """Good integers in [0, int(x)] (x has no leading zeros, may be "0")."""
        free = [0] * (max_sum + 1)        # prefixes strictly below x, by digit sum
        tight_sum = 0                     # digit sum of the prefix equal to x so far
        for ch in x:
            d = int(ch)
            nxt = [0] * (max_sum + 1)
            for s, ways in enumerate(free):
                if ways:
                    for dig in range(10):
                        if s + dig > max_sum:
                            break
                        nxt[s + dig] = (nxt[s + dig] + ways) % MOD
            for dig in range(d):          # branch off below x's digit
                if tight_sum + dig <= max_sum:
                    nxt[tight_sum + dig] = (nxt[tight_sum + dig] + 1) % MOD
            tight_sum += d
            free = nxt
        result = sum(free[min_sum:]) % MOD
        if min_sum <= tight_sum <= max_sum:
            result += 1                   # x itself
        return result % MOD

    def minus_one(x: str) -> str:
        digits = list(x)
        i = len(digits) - 1
        while digits[i] == "0":
            digits[i] = "9"
            i -= 1
        digits[i] = str(int(digits[i]) - 1)
        s = "".join(digits).lstrip("0")
        return s if s else "0"

    return (upto(num2) - upto(minus_one(num1))) % MOD
